window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:obstetricia-infeccoes-congenitas"]={"block":"anki:obstetricia-infeccoes-congenitas","label":"Anki · Infecções Congênitas","count":96,"questions":[{"id":"anki-obstetricia-infeccoes-congenitas-45ebcca677b06a8b","number":"0301s","sourceNumber":"0301s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Mulher de 36 anos de idade, primigesta, com idade gestacional de 38 semanas, é admitida na unidade de emergência com queixa de saída de secreção vaginal líquida há 3 horas e contrações irregulares. Ao exame clínico, apresenta dinâmica uterina de 2 contrações de 45 segundos em 10 minutos, líquido claro coletado em fundo de saco posterior visualizado em exame especular e toque vaginal com 5cm de dilatação cervical. À inspeção vulvar, são visualizadas lesões vesiculares e ulceradas, intensamente dolorosas, que segundo a paciente surgiram há 2 dias. Também relatou história de quadro semelhante anteriormente à gestação. A sorologia para HIV foi negativa e o VDRL foi de 1:8. A paciente nega ter realizado qualquer tratamento previamente. Qual é a conduta que deve ser adotada neste momento?","options":{"A":"Iniciar esquema de aciclovir e realizar assistência ao parto.","B":"Indicar a realização imediata de parto cesárea.","C":"Iniciar ocitocina para diminuir o tempo de trabalho de parto.","D":"Assistência ao trabalho de parto por via baixa."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320403","ankiGuid":"t5VBttO2Z6"},{"id":"anki-obstetricia-infeccoes-congenitas-96c2432bfcd066d4","number":"0302s","sourceNumber":"0302s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Há uma infecção congênita que ocorre, geralmente, por infecção genital materna. É mais comum sua transmissão durante o trabalho de parto ou pós-natal e chega a 50% no parto vaginal. Mulheres com primo-infecção geralmente são assintomáticas, enquanto aquelas com infecção recidivante têm a transmissão intraparto diminuída para uma taxa de 3% a 5% pela presença de anticorpos preexistentes. A alternativa correspondente à infecção é:","options":{"A":"Infecção congênita por herpes simples.","B":"Sífilis congênita precoce.","C":"Infecção congênita por citomegalovírus.","D":"Rubéola congênita."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320404","ankiGuid":"o-^n<SZEOR"},{"id":"anki-obstetricia-infeccoes-congenitas-914b8365a43ec015","number":"0303s","sourceNumber":"0303s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Quando a infecção por toxoplasmose é adquirida pela primeira vez durante a gravidez, os parasitas podem ser transmitidos da mãe para o feto, resultando em toxoplasmose congênita. Uma gestante de 14 semanas comparece à consulta trazendo resultados da primeira rotina laboratorial. Possui sorologia para toxoplasmose IgG não reagente e IgM não reagente. Qual a conduta mais correta a ser seguida?","options":{"A":"Considerar a paciente imune e tranquilizá-la com relação à doença.","B":"Solicitar teste de avidez para determinar quando houve a infecção e avaliar se há necessidade de tratamento.","C":"Iniciar o tratamento com Espiramicina imediatamente.","D":"Considerar a paciente não imunizada e repetir a sorologia no segundo e no terceiro trimestres, além de orientar sobre a alimentação e os riscos da infecção."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320406","ankiGuid":"k1U|`a$xF7"},{"id":"anki-obstetricia-infeccoes-congenitas-be6975b1769312c8","number":"0304s","sourceNumber":"0304s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Recém-nascido a termo, adequado para idade gestacional, filho de mãe hígida com pré-natal adequado, ultrassom morfológico normal. Sorologia de toxoplasmose com 7 semanas de gestação: IgM (método elisa) positivo, IgG positivo, com alta avidez. Exame clínico normal ao nascimento. A conduta recomendada é:","options":{"A":"realizar avaliação de fundo de olho, ultrassonografia transfontanela e abdominal, hemograma, punção lombar e sorologias do recém-nascido, antes de indicar o tratamento.","B":"coletar sorologia para toxoplasmose do sangue do cordão e indicar o tratamento dependendo do resultado.","C":"iniciar tratamento com sulfadiazina, pirimetamina e ácido folínico por um ano, independentemente do resultado de exames.","D":"realizar cuidados de rotina, não havendo necessidade de investigação diagnóstica ou de tratamento do recém- nascido."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320407","ankiGuid":"AMQO->k*&k"},{"id":"anki-obstetricia-infeccoes-congenitas-f222e6564adf512b","number":"0305s","sourceNumber":"0305s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Durante consulta de pré-natal na atenção primária, gestante apresenta os seguintes resultados de sorologia para toxoplasmose:\n\nAs condutas corretas são:","options":{"A":"espiramicina; encaminhar para a referência para realizar amniocentese.","B":"sulfadiazina, pirimetamina e ácido folínico; encaminhar para a referência para realizar amniocentese.","C":"espiramicina; não há necessidade de realizar a amniocentese.","D":"sulfadiazina, pirimetamina e ácido folínico; não há necessidade de realizar a amniocentese."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":["question_bank/media/obstetricia-infeccoes-congenitas/paste-8d5eab4b3dc3d7c8015d8aab9eb28a75362271cb.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320408","ankiGuid":"vaJ$Ubs16["},{"id":"anki-obstetricia-infeccoes-congenitas-01ab7580d95c9ccf","number":"0306s","sourceNumber":"0306s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"RKC, 32 anos, primigesta, consulta com 16 semanas de gestação em uso de Espiramicina 3g/dia desde as 10 semanas, quando apresentou IgG e IgM positivos para toxoplasmose. Com 12 semanas, o exame de avidez de IgG foi de 10% (avidez baixa). Assinalar a alternativa que apresenta o manejo adequado dessa gestante:","options":{"A":"Suspender a Espiramicina, pois os exames indicam infecção anterior à gravidez.","B":"Manter a Espiramicina intercalando com Sulfadiazina, Pirimetamina e Ácido Folínico.","C":"Manter a Espiramicina e indicar a realização da amniocentese com exame de reação em cadeia da polimerase (PCR) a partir de 18 semanas.","D":"Trocar o tratamento para Sulfadiazina, Pirimetamina e Ácido Folínico."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320409","ankiGuid":"rHDP12lY5Y"},{"id":"anki-obstetricia-infeccoes-congenitas-b8925346fefa3abe","number":"0307s","sourceNumber":"0307s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Uma gestante de 25 anos de idade, com 11 semanas de gestação, traz à consulta do pré-natal uma sorologia positiva para Toxoplasmose (IgM e IgG positivas). O próximo passo investigativo seria:","options":{"A":"Amniocentese para pesquisa de PCR de T.gondii","B":"Iniciar sulfadiazina + pirimetamina.","C":"Iniciar espiramicina com 18 semanas de gestação.","D":"Solicitar teste de avidez de IgG.","E":"Acompanhar com ultrassonografias seriadas."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320410","ankiGuid":"Oj*^/H[-pp"},{"id":"anki-obstetricia-infeccoes-congenitas-40d0ff9f1d707213","number":"0308s","sourceNumber":"0308s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Para quais gestantes é necessário fornecer orientações sobre prevenção de infecção congênita pelo citomegalovírus?","options":{"A":"Para todas, independente do estado sorológico.","B":"Somente para as que apresentem IgG negativa.","C":"Somente para aquelas com baixa avidez de IgM.","D":"Somente para as que apresentem tanto IgG quanto IgM negativas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320411","ankiGuid":"x%quFkis6r"},{"id":"anki-obstetricia-infeccoes-congenitas-7a5c33d5daf4d226","number":"0309s","sourceNumber":"0309s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Paciente é atendida em consulta de pré-natal na décima semana de gestação, sem comorbidades, apresentando sorologia para toxoplasmose com IgG e IgM positivos e teste de avidez para IgG com alta avidez. A conduta diante desses resultados é:","options":{"A":"prescrição de espiramicina","B":"manutenção de pré-natal habitual","C":"encaminhamento para amniocentese após 16 semanas","D":"início de sulfadiazina com pirimetamina, alternada com ácido folínico"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320412","ankiGuid":"mjrTL&JxZ5"},{"id":"anki-obstetricia-infeccoes-congenitas-f1e47973f1787fa4","number":"0310s","sourceNumber":"0310s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Com relação à infecção por toxoplasmose na gravidez, assinale a alternativa correta.","options":{"A":"Na maior parte das vezes, a infecção aguda apresenta-se como síndrome mono-like e a infecção subclínica ocorre apenas em 10% dos casos.","B":"A presença de IgM positivo e IgG positivo com 26 semanas de gestação indica a realização de teste de avidez da IgG.","C":"O risco de transmissão vertical é diretamente proporcional à idade gestacional.","D":"Na presença de infecção aguda materna confirmada na gravidez, é necessário o tratamento com sulfadiazina, pirimetamina e ácido folínico.","E":"A infecção fetal pelo Toxoplasma gondii pode ser diagnosticada por ultrassonografia, pois 70% dos fetos apresentam alterações ultrassonográficas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320413","ankiGuid":"lF@z:HNJ/H"},{"id":"anki-obstetricia-infeccoes-congenitas-beba7697239f1f03","number":"0311s","sourceNumber":"0311s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"M.A.S., 18 anos, G2P1NA0, IG: 39 semanas e 6 dias, admitida em pronto atendimento com queixa de contrações frequentes. Nega comorbidades, mas refere aparecimento de lesões dolorosas na vulva há uma semana. Ao exame: dinâmica uterina 3 contrações de 40 segundos em 10 minutos, BCF: 138 bpm, colo 70% apagado, centralizado, 08 cm de dilatação, bolsa íntegra, cefálico, plano 0 De Lee. Inspeção da vulva com lesões bolhosas e dolorosas de acordo com imagem abaixo.\n\nAssinale a alternativa que apresenta a correta associação entre o agente etiológico e a via de parto que deve ser orientada.","options":{"A":"Herpes simples (HSV-1/HSV-2), encaminhar imediatamente para cesárea, para reduzir os riscos de transmissão vertical.","B":"Papilomavírus humano (HPV), realizar a assistência ao parto vaginal, pois não há riscos de transmissão vertical.","C":"Papilomavírus humano (HPV), encaminhar imediatamente para cesárea, para reduzir os riscos de transmissão vertical.","D":"Herpes simples (HSV-1/HSV-2), realizar a assistência ao parto vaginal, pois não há risco de transmissão vertical."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":["question_bank/media/obstetricia-infeccoes-congenitas/paste-c8e525e0cdf0644862e2bd799e8fc0acabc2f658.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320414","ankiGuid":"uhp%}L3D^x"},{"id":"anki-obstetricia-infeccoes-congenitas-739fd4d87400fe77","number":"0312s","sourceNumber":"0312s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Primigesta com 10 semanas de gestação trouxe à consulta resultados de exames sorológicos para toxoplasmose realizados há 1 semana, evidenciando IgG não reagente e IgM reagente. Com base nesses resultados, assinale a alternativa que contempla a conduta correta:","options":{"A":"Iniciar espiramicina imediatamente, solicitar teste de avidez para IgG e repetir as dosagens de IgG e IgM em 3-4 semanas para datação da fase aguda.","B":"Iniciar sulfadiazina, pirimetamina e ácido folínico imediatamente e repetir as dosagens de IgG e IgM em 3-4 semanas.","C":"Solicitar coleta imediata de material para dosagens de IgG, IgM, IgA e IgE e teste de avidez para IgG e programar cordocentese em 2-3 semanas para pesquisa de IgM específica.","D":"Solicitar teste de avidez para IgG e oferecer a possibilidade de realização imediata de punção de líquido amniótico para PCR para investigação da infecção fetal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320415","ankiGuid":"m:FVR&k7[:"},{"id":"anki-obstetricia-infeccoes-congenitas-c7056349ccf41533","number":"0314s","sourceNumber":"0314s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"G1P0A1, idade gestacional de 9 semanas, volta à consulta de pré-natal trazendo os seguintes exames para toxoplasmose: I g G reagente e IgM reagente. Foi solicitado o teste de avidez IgG específico, que apresentou como resultado alta avidez. Nesse caso, devemos considerar","options":{"A":"infecção aguda.","B":"infeção materna e fetal.","C":"paciente suscetível.","D":"infecção adquirida há menos de 4 meses.","E":"infecção adquirida há mais de 4 meses."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320417","ankiGuid":"n_oJHH0]i|"},{"id":"anki-obstetricia-infeccoes-congenitas-985b4dac93234c30","number":"0315s","sourceNumber":"0315s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"A rubéola é uma infecção viral que, nas últimas décadas, teve a incidência e a prevalência diminuídas drasticamente no Brasil. Considerando o rastreio da rubéola no pré-natal, é INCORRETO afirmar:","options":{"A":"O rastreio para a rubéola no pré-natal, atualmente, deve, em todos os casos, ser realizado com os exames de primeiro trimestre, que incluam hemograma completo; tipagem sanguínea; glicemia de jejum; urina I; urocultura; sorologias para toxoplasmose, sífilis, hepatite B, hepatite C e HIV; TSH; protoparasitológico de fezes; ultrassom de primeiro trimestre.","B":"Devido à eliminação da rubéola e da síndrome da rubéola congênita no Brasil, o Ministério da Saúde recomenda que não seja realizado o exame sorológico com pesquisa de IgM para rubéola na rotina de pré-natal para gestantes, em casos de mulheres assintomáticas.","C":"A grande quantidade de exames sorológicos com pesquisa de IgM para rubéola resulta em um número alto de falsos positivos, acumulando casos suspeitos de rubéola que não correspondem à definição de caso da doença.","D":"Caso exista a necessidade de saber se a gestante tem títulos protetores para o vírus da rubéola, é recomendado solicitar apenas o IgG. Mesmo que a mulher seja negativa, não poderá utilizar a vacina dupla (sarampo-rubéola) ou a tríplice viral (sarampo-rubéola-caxumba) durante a gestação."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320418","ankiGuid":"Di^KTjAR1t"},{"id":"anki-obstetricia-infeccoes-congenitas-77efe9c2ce8f7fad","number":"0316s","sourceNumber":"0316s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Leia o caso clínico a seguir. Uma gestante apresentou no teste da mamãe, realizado com dez semanas de gestação, IgM e IgG para toxoplasmose positivos. Após este resultado, ainda com doze semanas de gestação, foi realizada a avidez para IgG que resultou em 80%. No segundo trimestre de gestação, a gestante realizou a amniocentese para a realização de reação de cadeia de polimerase (PCR) para detecção do Toxoplasma gondii, que resultou negativo. Ao nascimento, com 38 semanas de idade gestacional, o recém-nascido apresentava IgM negativo, IgG em níveis semelhantes ao materno e a mãe apresentava, nesta ocasião, IgM e IgG positivos. Nesse caso, a melhor conduta é:","options":{"A":"tratar o recém-nascido porque a gestante teve toxoplasmose comprovada durante gestação.","B":"tratar o recém-nascido porque a gestante teve toxoplasmose provável durante gestação.","C":"não tratar o recém-nascido porque é improvável que a gestante tenha tido toxoplasmose durante gestação.","D":"não tratar o recém-nascido porque a gestante não teve toxoplasmose durante gestação."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320419","ankiGuid":"e-1:@Lz|x{"},{"id":"anki-obstetricia-infeccoes-congenitas-188a23be95c83d4d","number":"0317s","sourceNumber":"0317s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Uma gestante com início tardio de pré-natal e 26 semanas, no retorno em consulta, entre os exames solicitados, tinha sorologia de toxoplasmose com IgM positivo e IgG positivo. Considerando o resultado da sorologia e a idade gestacional, nesse caso hipotético, assinale a alternativa correta.","options":{"A":"É necessária a realização de teste de avidez da IgG para, assim, determinar se a infecção por toxoplasmose é aguda.","B":"Deve-se iniciar espiramicina e realizar amniocentese com pesquisa de PCR para Toxoplasma gondii.","C":"Deve-se iniciar espiramicina, não havendo necessidade de amniocentese ou pesquisa de PCR para Toxoplasma gondii.","D":"Não se deve iniciar espiramicina, mas é necessário realizar amniocentese com pesquisa de PCR para Toxoplasma gondii, só iniciando a terapia após o resultado de PCR.","E":"Deve-se iniciar tratamento com pirimetamina, sulfadiazina e ácido folínico."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320420","ankiGuid":"Q#_tv+MBz>"},{"id":"anki-obstetricia-infeccoes-congenitas-aae68f5e89c6bc06","number":"0318s","sourceNumber":"0318s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Durante o pré-natal é rotineira a solicitação de exames de sífilis. Assim, pode-se considerar sobre rastreamento indicado pelo protocolo Mãe Curitibana, Versão 2021:","options":{"A":"O exame inicial recomendado é o VDRL, teste não treponêmico, mais sensível que os treponêmicos na sífilis latente.","B":"Se na primeira etapa o teste for negativo, considera-se gestante sem sífilis, mas a evidência epidemiológica pode exigir repetir o teste.","C":"A segunda etapa é feita com teste treponêmico se o primeiro teste, não treponêmico, for negativo.","D":"O teste rápido não pode também ser utilizado na Terceira etapa."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320421","ankiGuid":"F&Ei_}7-yj"},{"id":"anki-obstetricia-infeccoes-congenitas-c9a088ac2065250d","number":"0319s","sourceNumber":"0319s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Primigesta, assintomática, sem patologias prévias, iniciou acompanhamento de pré-natal com 8 semanas de idade gestacional (IG). Foram realizados, entre outros exames, os testes para triagem de toxoplasmose. Inicialmente, o resultado foi anticorpos IgM positivos e anticorpos IgG negativos. Com esse resultado, o médico optou por repetir os mesmos exames 15 dias depois. A gestante só retornou para consulta com 16 semanas de IG e a nova sorologia para toxoplasmose apresentou anticorpos IgM e IgG positivos. Com base nos protocolos da Federação Brasileira das Associações de Ginecologia e Obstetrícia, assinale a alternativa que apresenta a conduta a ser tomada.","options":{"A":"Realização de avidez de anticorpos IgG em nova amostra, para afastar a possibilidade de anticorpos IgM residuais de infecção antiga.","B":"Indicar imediatamente amniocentese para o diagnóstico de possível infecção fetal.","C":"Iniciar tratamento com espiramicina, na dose de 3 g por dia, e programar amniocentese para ser realizada após 18 semanas.","D":"Iniciar o tratamento com espiramicina, alternando-se de três em três semanas com sulfadiazina, pirimetamina e ácido folínico, bem como a realização de USG morfológico.","E":"Em razão dos exames sorológicos para toxoplasmose terem sido discordantes, antes de iniciar a medicação, repetir os testes sorológicos para detecção dos anticorpos IgM e IgG"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320422","ankiGuid":"qXMYID{h:^"},{"id":"anki-obstetricia-infeccoes-congenitas-16af3bfcf595d5c6","number":"0320s","sourceNumber":"0320s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Analise as assertivas abaixo em relação a infecções na gestação: I. O risco de transmissão na soroconversão para a toxoplasmose aumenta com o evoluir da gestação. II. Em geral, o VDRL ( Venereal Disease Research Laboratory ) torna-se positivo 1 a 3 semanas após o aparecimento do cancro duro. III. A transmissão vertical para o HIV (AIDS) está estimada em 25%, caso nenhuma medida preventiva seja tomada. Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"I, II e III."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320423","ankiGuid":"Jk.?[VL;r{"},{"id":"anki-obstetricia-infeccoes-congenitas-9a3f3fb8d0aa2f98","number":"0321s","sourceNumber":"0321s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Recém-nascido, sexo masculino, nascido de parto vaginal a termo, apresentou Apgar 7 (1’) e 9 (5’), peso de 3.520 g e exame físico normal. Os dados no cartão de pré-natal evidenciam presença de anticorpos IgM e IgG com 80% de avidez contra o T. gondii, realizados na primeira consulta com 7 semanas. Em relação à toxoplasmose, entre as seguintes condutas iniciais, a melhor para este recém-nascido é","options":{"A":"não realizar maiores investigações.","B":"realizar exames para o diagnóstico de toxoplasmose congênita.","C":"iniciar tratamento para toxoplasmose congênita.","D":"solicitar a avaliação do infectologista."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320424","ankiGuid":"zq_?.vCqM"},{"id":"anki-obstetricia-infeccoes-congenitas-236df5989a3277c0","number":"0322s","sourceNumber":"0322s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Primigesta, 23 anos, branca, amasiada, do lar, idade gestacional: 11 semanas. Vem à consulta de retorno pré-natal, na Unidade Básica de Saúde, para checar resultados de exames descritos a seguir: Hemoglobina: 12,6 g/dl; hematócrito: 40%. Sorologia para toxoplasmose (quimioluminescência): IgG reagente e IgM reagente. Qual o melhor manejo para essa gestante no pré-natal de origem?","options":{"A":"Repetir sorologia para toxoplasmose.","B":"Encaminhar para realização de amniocentese.","C":"Realizar orientações profiláticas e repetir sorologia.","D":"Iniciar espiramicina e solicitar teste avidez."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320425","ankiGuid":"Anr@{?|p%M"},{"id":"anki-obstetricia-infeccoes-congenitas-00866f80e4380e27","number":"0323s","sourceNumber":"0323s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Primigesta com idade gestacional de 29 semanas comparece à sua 4° consulta de pré-natal. Fez todos os exames recomendados na sua rotina de primeiro trimestre; mostrou sorologia para toxoplasmose IgG- negativo e IgM- negativo. Hoje, apresenta exames realizados na semana anterior, cuja sorologia de toxoplasmose apresenta-se IgG- negativo e IgM positivo. Marque a alternativa que melhor se aplica à condução desta gestante:","options":{"A":"Iniciar espiramicina imediatamente e repetir sorologia em 3 semanas.","B":"Iniciar espiramicina, pirimetamina, sulfadiazina e ácido folínico. Repetir sorologia em 3 semanas.","C":"Iniciar espiramicina e solicitar teste de avidez de IgG.","D":"Solicitar teste de avidez de IgG, iniciar espiramicina apenas se resultado compatível com baixa avidez.","E":"Solicitar teste de avidez de IgG e iniciar espiramicina. Iniciar pirimetamina, sulfadiazina e ácido folínico apenas se houver evidência de infecção fetal (Reação em cadeia da polimerase/PCR ou alteração ultrassonográfica)."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320426","ankiGuid":"hX>Pm`9;gT"},{"id":"anki-obstetricia-infeccoes-congenitas-81f0d93bf1451037","number":"0324s","sourceNumber":"0324s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"A toxoplasmose congênita é uma infecção de difícil diagnóstico e constitui um grande problema de saúde pública pela elevada morbimortalidade a ela associada. Sobre essa doença, assinale a alternativa correta.","options":{"A":"A maioria dos recém-nascidos (70%) com infecção congênita por toxoplasmose são sintomáticos.","B":"O risco de transmissão materno-fetal diminui com o avançar da gestação.","C":"O grau de comprometimento do concepto é menor quando a infecção ocorre no início da gestação.","D":"A sorologia negativa de anticorpos da classe IgM no recém-nascido exclui o diagnóstico de infecção congênita.","E":"A dosagem simultânea e seriada de anticorpos da classe IgG da mãe e do recém-nascido é utilizada no diagnóstico laboratorial."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320427","ankiGuid":"k)zO9.6SWh"},{"id":"anki-obstetricia-infeccoes-congenitas-cb646c7dc95a3b7a","number":"0325s","sourceNumber":"0325s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"herpes Diagnóstico na gestação Mariana, 22 anos, compareceu à consulta médica de pré-natal com resultados dos exames solicitados pela enfermeira há um mês. O resultado da sorologia para toxoplasmose foi IgM e IgG positivos. Todos os outros exames estavam normais. Foi realizado teste de avidez de IgG na mesma amostra, evidenciando forte avidez de IgG. Mariana está com 13 semanas de gestação. Sua conduta enquanto responsável pelo pré-natal de Mariana é:","options":{"A":"Prescrever espiramicina.","B":"Orientar Mariana que se trata de infecção adquirida antes da gravidez.","C":"Prescrever pirimetamina, sulfadiazina e ácido folínico.","D":"Encaminhar imediatamente para o infectologista."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320428","ankiGuid":"rd#)G.q&,5"},{"id":"anki-obstetricia-infeccoes-congenitas-9f9aaaa3a0576f23","number":"0326s","sourceNumber":"0326s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante de 23 anos de idade está em sua primeira gestação. Iniciou o pré-natal com 19 semanas de gestação. Está em acompanhamento irregular na UBS pois trabalha como atendente em um pet Shop e está sem tempo para as consultas. Vem encaminhada ao pré-natal de alto risco com 25 semanas de gestação com os exames descritos a seguir.\n\nQual é a conduta pré-natal imediata?","options":{"A":"Iniciar ácido fólico em dose dobrada.","B":"Iniciar pirimetamina associada a sulfadiazina.","C":"Iniciar espiramicina isolada.","D":"Iniciar espiramicina associada a pirimetamina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":["question_bank/media/obstetricia-infeccoes-congenitas/paste-73b9e6e78c1094a5ee2bf43486ab8fa4c06f74b3.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320429","ankiGuid":"JyT2P>|_P1"},{"id":"anki-obstetricia-infeccoes-congenitas-e5b2b1fb02e089f8","number":"0327s","sourceNumber":"0327s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Que tratamento, dentre os abaixo, é o mais adequado para toxoplasmose congênita confirmada durante a gestação?","options":{"A":"Espiramicina","B":"Espiramicina e ácido fólico","C":"Pirimetamina, sulfadiazina e ácido fólico","D":"Pirimetamina, sulfadiazina e azitromicina"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320430","ankiGuid":"H*8D]r#yig"},{"id":"anki-obstetricia-infeccoes-congenitas-3a907b62d506cfaa","number":"0328s","sourceNumber":"0328s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante, 22 anos, G2P1, com 10 semanas de gestação, chega para consulta de retorno d epré-natal com os seguintes resultados sorológicos para toxoplasmose: ELISA-IgM = positivo e ELISA-IgG = positivo. Qual seria sua conduta?","options":{"A":"Solicitar o teste de avidez de IgG para toxoplasmose e iniciar tratamento materno imediato com clindamicina e sulfa.","B":"Solicitar o teste de avidez de IgG para toxoplasmose e iniciar espiramicina.","C":"Solicitar o teste de avidez de IgG para toxoplasmose e iniciar o tratamento da infecção fetal com sulfa e pirimetamina.","D":"Fazer cordocentese ou amniocentese para pesquisa de DNA do Toxoplasma gondii.","E":"Iniciar sulfadiazina, pirimetamina e ácido folínico de imediato, visto que a paciente está no primeiro trimestre."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320431","ankiGuid":"Q<Tut[uOyJ"},{"id":"anki-obstetricia-infeccoes-congenitas-f4bad69a5f4d8e99","number":"0329s","sourceNumber":"0329s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Primípara de 28 anos, 39 semanas de gestação, em trabalho de parto, apresenta ruptura da bolsa há 3 horas e refere história de lesões dolorosas na vulva há 4 dias. Exame físico: extensa placa eritematoedematosa, com exulcerações nos pequenos lábios (imagem a seguir). Exame citológico direto: células multinucleadas e núcleos com aspecto de vidro fosco.\n\nA conduta imediata é","options":{"A":"cesariana e sorologia para herpes vírus.","B":"parto vaginal e penicilina cristalina.","C":"cesariana e aciclovir.","D":"parto vaginal e ganciclovir."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":["question_bank/media/obstetricia-infeccoes-congenitas/paste-e501fe13212eb40665ebf99850f9670ebe953baa.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320432","ankiGuid":"HSeNpR,ufo"},{"id":"anki-obstetricia-infeccoes-congenitas-448012284b2f2a49","number":"0330s","sourceNumber":"0330s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante de 6 semanas traz resultado de sorologia para toxoplasmose com IgM positiva e IgG positiva, com teste de avidez de IgG de 80%. É correto afirmar que?","options":{"A":"Trata-se de infecção recente, passível de tratamento clínico.","B":"Provavelmente a infecção ocorreu antes da gestação.","C":"O teste é inconclusivo, devendo-se repeti-lo em 6 semanas.","D":"O teste indica infecção tratada anteriormente."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320433","ankiGuid":"g._?q*fXqk"},{"id":"anki-obstetricia-infeccoes-congenitas-2c78af470ed76f7d","number":"0331s","sourceNumber":"0331s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Quanto às infecções virais na gestação e as repercussões fetais e neonatais relacionadas, pode-se afirmar que","options":{"A":"O American College of Obstetricians and Gynaecologists (ACOG, 2007) recomenda quea escolha da via de parto seja obstétrica em gestantes com lesões ativas de herpes genital, pois a cesárea não reduz significativamente o risco de infecção do recém-nascido pelo herpes-vírus simples (HSV).","B":"gestantes com lesões herpéticas devem ser tratadas apenas com antivirais tópicos uma vez que drogas como Aciclovir, Fanciclovir ou Valaciclovir, se ingeridas via oral, atravessam a barreira placentária e podem causar efeitos teratogênicos no feto.","C":"a infecção pelo parvovírus B19 durante a gravidez pode estar associada a anemia e hidropsia fetais.","D":"a soropositividade materna IgG anti-citomegalovírus (IgG anti-CMV) previne infecçõe srecorrentes durante a gravidez e protege contra a transmissão vertical.","E":"segundo o Ministério da Saúde (2013), a terapia antirretroviral (TARV) nas gestantesinfectadas pelo vírus da imunodeficiência humana (HIV) deve ser indicada conforme critérios clínicos e imunológicos, principalmente os níveis de linfócitos T CD4+."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320434","ankiGuid":"wu*QJr-.,."},{"id":"anki-obstetricia-infeccoes-congenitas-c72aec99bbd92576","number":"0332s","sourceNumber":"0332s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"A toxoplasmose na gestação é transmitida ao feto pela via transplacentária na forma de:","options":{"A":"oocisto.","B":"cisto.","C":"esporozoíto.","D":"taquizoíto."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320435","ankiGuid":"wtN6QNy+v7"},{"id":"anki-obstetricia-infeccoes-congenitas-484a27c769145fff","number":"0333s","sourceNumber":"0333s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Frente a gestante com sorologia negativa para toxoplasmose, é recomendado orientá-la a evitar:","options":{"A":"consumo ou manipulação de carne crua.","B":"contato com pássaros.","C":"aglomerações de pessoas.","D":"locais com baixa circulação de ar."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320436","ankiGuid":"ejqF(-U-aN"},{"id":"anki-obstetricia-infeccoes-congenitas-787298c86aaea39c","number":"0334s","sourceNumber":"0334s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Paciente primigesta, com Idade Gestacional de 12 semanas, comparece à consulta pré-natal com resultado de exames de rotina evidenciando sorologia para toxoplasmose IGG positivo e IGM positivo. Qual a melhor conduta?","options":{"A":"Indicar imediatamente amniocentese, para pesquisa de PCR no líquido amniótico.","B":"Solicitar teste de avidez para IGG e, se baixa avidez, iniciar profilaxia com Espiramicina.","C":"Solicitar teste de avidez para IGG e, se alta avidez, iniciar tratamento com Espiramicina.","D":"Iniciar tratamento para toxoplasmose aguda com esquema tríplice: Pirimetamina + Sulfadiazina, intercalados com Espiramicina."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320437","ankiGuid":"kAuA}n2Q2-"},{"id":"anki-obstetricia-infeccoes-congenitas-64084e5d1721ae67","number":"0335s","sourceNumber":"0335s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"A infecção pelo Zika vírus constitui-se uma preocupação no acompanhamento pré-natal no Brasil devido à sequela da microcefalia no recém-nascido causada pela infecção, o que se constitui um grave problema de Saúde Pública. Diante do exposto é importante que o médico tenha conhecimento sobre a infecção pelo vírus na gestação, então, das questões abaixo, qual a afirmação VERDADEIRA?","options":{"A":"Embora o Zika vírus seja encontrado no leite materno no caso de infecção aguda a amamentação não é contraindicada.","B":"O uso de repelentes ambientais do tipo spray é eficaz contra o mosquito vetor da Zika.","C":"O repelente a base de Icaridina e a ingestão de tiamina pela gestante são eficazes na proteção contra o mosquito vetor da Zika e aprovados pela ANVISA.","D":"Para um correto diagnóstico ultrassonográfico da microcefalia fetal é necessário apenas saber a data da última menstruação da gestante."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320438","ankiGuid":"EOX5?{^05-"},{"id":"anki-obstetricia-infeccoes-congenitas-537f9c38722b181f","number":"0336s","sourceNumber":"0336s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Paciente, G2PN1A0, IG:26 semanas, realizou a 1ª sorologia para Toxoplasmose tardiamente, com resultado IgG e IgM POSITIVOS, tendo sido prescrita Espiramicina. Foi encaminhada para realização de amniocentese, com resultado NEGATIVO para pesquisa de infecção fetal. Qual a conduta adequada?","options":{"A":"Suspender o uso da Espiramicina","B":"Realizar teste de avidez de IgG","C":"Iniciar Pirimetamina, Sulfadiazina e Ácido Folínico","D":"Manter o uso da Espiramicina até o parto"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320439","ankiGuid":"F!dk50E!2,"},{"id":"anki-obstetricia-infeccoes-congenitas-d2ae61eb48ef4d33","number":"0337s","sourceNumber":"0337s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"A hidropsia fetal é definida pelo acúmulo anormal de líquido em pelo menos dois ou mais compartimentos corporais fetais. São causas de hidropsia fetal não imune, EXCETO:","options":{"A":"cromossomopatia.","B":"infecção por parvovírus.","C":"doença hemolítica perinatal.","D":"cardiopatia com hipoplasia das cavidades esquerdas.","E":"síndrome da transfusão feto-fetal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320440","ankiGuid":"b?Sy8yfsRS"},{"id":"anki-obstetricia-infeccoes-congenitas-3444ada0e7751036","number":"0338s","sourceNumber":"0338s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"A infecção aguda por Toxoplasma gondii durante a gestação pode trazer desfechos potencialmente graves para o recém- nascido. O acompanhamento pré-natal adequado, incluindo pesquisa sorológica e orientações às gestantes suscetíveis, permite a prevenção e tratamento adequado da infecção. A maioria das gestantes com infecção aguda adquirida não apresenta sinais ou sintomas da doença. A realização de sorologia com anticorpos IgG e IgM para Toxoplasma gondii está indicada durante o pré-natal. A necessidade de realização do teste de avidez de IgG durante o primeiro trimestre ocorre quando há o seguinte achado sorológico:","options":{"A":"IgM reativo/ IgG reativo.","B":"IgM reativo/ IgG não reativo.","C":"IgM não reativo/ IgG reativo.","D":"IgM não reativo/ IgG não reativo.","E":"deve ser sempre solicitado, independente da sorologia."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320441","ankiGuid":"FLi<6Pm.[8"},{"id":"anki-obstetricia-infeccoes-congenitas-aea0faae8156d6c4","number":"0339s","sourceNumber":"0339s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Em uma área endêmica para o vírus Zika é recomendado à gestante:","options":{"A":"O uso de preservativos pelo companheiro até o final da gravidez.","B":"Evitar uso de repelentes contendo icaridina no primeiro trimestre da gravidez.","C":"Realizar ultrassonografia obstétrica e sorologia para Zika vírus todos os meses.","D":"Realizar exames laboratoriais para Zika vírus a cada dois meses."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320442","ankiGuid":"G+l~&)NR}0"},{"id":"anki-obstetricia-infeccoes-congenitas-84e25dbf6a3411ce","number":"0340s","sourceNumber":"0340s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante com 37 semanas e 5 dias apresenta metrossistoles 4/10’/50’’, colo 90% apagado, dilatado 2cm, com a bolsa íntegra. O exame da vulva revela múltiplas lesões vesiculosas, algumas ulceradas, que segundo a paciente surgiram há poucos dias e que nunca apresentou quadro clínico semelhante anteriormente. Qual a conduta mais adequada para o caso?","options":{"A":"Aciclovir por via oral durante 7 dias.","B":"Tocólise e aciclovir por 7 dias.","C":"Aguardar evolução do trabalho de parto e tratar a infecção no puerpério com aciclovir por via oral durante 7 dias.","D":"Indicar cesariana.","E":"Iniciar tratamento com aciclovir venoso e aguardar evolução do parto."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320443","ankiGuid":"GZb-^+Wawc"},{"id":"anki-obstetricia-infeccoes-congenitas-391d9f8ae3a94aeb","number":"0341s","sourceNumber":"0341s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante na 10.a semana apresenta IgG e IgM positivas para toxoplasmose. A pesquisa de avidez da IgG revela taxas de alta avidez. Qual a conduta mais adequada para o caso?","options":{"A":"Recomendar a interrupção da gravidez.","B":"Amniocentese com 16 semanas para fazer PCR do líquido amniótico.","C":"Orientar o casal que a infecção é passada.","D":"Sulfadizina e pirimetamina.","E":"Espiramicina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320444","ankiGuid":"sVoBdv!L<Q"},{"id":"anki-obstetricia-infeccoes-congenitas-5fba1c422a28704d","number":"0342s","sourceNumber":"0342s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Paciente 18 anos, 10 semanas de gestação em acompanhamento pré-natal. Á sorologia apresentou IgG e IgM positivo para toxoplasmose. A conduta mais adequada é:","options":{"A":"Conservadora. Paciente IgG positivo é imune à doença e por isso não há risco de infecção fetal.","B":"Realizar teste de avidez de IgG, se alta iniciar o tratamento","C":"Repetir sorologia trimestralmente e verificar se houve alguma alteração","D":"Realizar teste de avidez de IgG, se baixa iniciar o tratamento"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320445","ankiGuid":"wMW]9rTjVX"},{"id":"anki-obstetricia-infeccoes-congenitas-c481be2efbc3f41a","number":"0343s","sourceNumber":"0343s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"A toxoplasmose durante a gestação deve ser tratada tão precoce quanto possível. Se no município em que a gestante acompanha o pré-natal não for possível realizar PCR de líquido amniótico, o tratamento deve ocorrer seguinte maneira, exceto:","options":{"A":"Até 16 semanas usar apenas espiramicina.","B":"Entre 17 e 33 semanas deve ser utilizado Sulfadiazina, pirimetamina e ácido folínico.","C":"A partir de 34 semanas usar apenas espiramicina.","D":"Suspender todas as medicações com 36 semanas.","E":"Se o diagnóstico for com 30 semanas devemos iniciar com sulfadiazina, pirimetamina e ácido folínico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320446","ankiGuid":"_miiZ-%)>"},{"id":"anki-obstetricia-infeccoes-congenitas-67e6ef03caf2815c","number":"0344s","sourceNumber":"0344s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"A epidemia do Zika vírus em 2016 nas Américas, no Caribe e no Pacífico, foi ainda mais alarmante em razão das descrições de microcefalia e malformações no sistema nervoso central nos fetos das gestantes acometidas passando a integrar o grupo das doenças relacionadas com infecção congênita nos recordando na importância do estudo desse tema. Portanto avalie a seqüência de afirmações a seguir classificando-as em verdadeiras (V) ou falsas (F). (A) - A infecção pelo ZIKA VÍRUS pode ser assintomática ou apresentar sintomas gerais como febre baixa, eritema pruriginoso, artralgia, mialgia e mal estar, ou ainda cursar com complicações neurológicas em adultos como síndrome de Guillain-Barré, encefalite, mielite transversa e meningo encefalite. ( ); (B) - A sorologia para CITOMEGALOVÍRUS (IgG positivo e IgM negativo) confere imunidade permanente para a infecção, excluindo a possibilidade dessa infecção congênita durante a gestação. ( ); (C) - A RUBEOLA é uma infecção congênita passível de prevenção por meio da vacinação durante a gestação dos casos susceptíveis (IgG negativo e IgM negativo), evitando as seqüelas da tríade clássica: cardiopatia, catarata e surdez. ( ); (D) - A TOXOPLASMOSE deve ser rastreada durante a gestação. Caso a sorologia do primeiro trimestre da gestação apresente IgG positivo e IgM positivo deve ser realizado o teste da avidez para IgG da toxoplasmose e se apresentar alta avidez indica que a infecção foi prévia a gestação. ( ); (E) - A PARVOVIROSE é causada pelo parvovírus B19 que apresenta ação citotóxica na eritropoiese o que pode resultar em anemia e ou hidropsia fetal. ( ).","options":{"A":"(A é (V; (B é (V; (C é (F; (D é (V; (E é (F","B":"(A é (F; (B é (F; (C é (V; (D é (V; (E é (V","C":"(A é (V; (B é (F; (C é (F; (D é (V; (E é (V","D":"(A é (V; (B é (F; (C é (V; (D é (F; (E é (V","E":"(A é (V; (B é (V; (C é (F; (D é (V; (E é (F"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320447","ankiGuid":"dJ&cH`I/]9"},{"id":"anki-obstetricia-infeccoes-congenitas-232455a66e51d94a","number":"0345s","sourceNumber":"0345s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"A infecção pelos vírus da herpes simples tipos 1 e 2 é extremamente comum em mulheres na idade fértil. Estima-se que sua prevalência aproxime-se de 70% em gestantes. Sobre a infecção fetal por essa patologia, assinale a alternativa correta.","options":{"A":"Geralmente, é fatal na infecção materna ativa em qualquer idade gestacional.","B":"Quanto maiores os sintomas maternos, maior o risco de transmissão para o feto.","C":"A infecção primária materna correlaciona-se com maiores riscos de infecção fetal.","D":"A indicação da via de parto será cesariana em caso de lesões ativas, independentemente do local das lesões.","E":"Em casos de reativação da infecção materna, maior será o risco de transmissão vertical comparada à primoinfecção."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320448","ankiGuid":"vYf~rBF3<#"},{"id":"anki-obstetricia-infeccoes-congenitas-a8eeeae35364e516","number":"0346s","sourceNumber":"0346s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"toxoplasmose Em relação à toxoplasmose na gestação, assinale a alternativa incorreta.","options":{"A":"A transmissão fetal aumenta de 15% para 60% entre o primeiro e o terceiro trimestre de gestação.","B":"Os anticorpos IgM são detectados a partir do sétimo dia, e os anticorpos IgG, a partir do 14º dia após a contaminação materna.","C":"O teste de avidez de IgG deve ser realizado nas situações de IgM positivo e IgG negativo, até o quarto mês de gestação, para avaliar se a contaminação materna foi antes ou após a concepção.","D":"Confirmada a infecção fetal, através da reação em cadeia da polimerase (PCR), deve-se iniciar sulfadiazina, pirimetamina e ácido folínico."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320449","ankiGuid":"QPno6%@_*Q"},{"id":"anki-obstetricia-infeccoes-congenitas-5f75d990a3903783","number":"0347s","sourceNumber":"0347s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Paciente de 28 anos, G2P1A0, IG: 12 semanas e 3 dias em acompanhamento pré-natal na UBS, comparece com resultado de exames do primeiro trimestre. Entre eles, a sorologia de toxoplasmose se apresenta da seguinte maneira: IgG: reativo lgM: reativo. Assinale a alternativa correta","options":{"A":"Solicitar o teste de avidez de IgG.","B":"Solicitar o teste de avidez de IgG. Se o resultado for de baixa avidez ou avidez intermediária, implica infecção antes da gestação.","C":"Solicitar o teste de avidez de IgG e iniciar o tratamento com espiramicina. Se o resultado for de alta avidez, implica em infecção recente.","D":"Iniciar espiramicina apenas após o resultado do teste de avidez de IgG.","E":"Iniciar imediatamente espiramicina, pirimetamina, sulfadiazina e ácido folínico."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320450","ankiGuid":"JpA}ofji`x"},{"id":"anki-obstetricia-infeccoes-congenitas-0948a48836df1a29","number":"0348s","sourceNumber":"0348s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"gestação O Toxoplasma Gondii é um protozoário intracelular obrigatório, distribuído em quase todas as regiões do mundo. Sobre essa afecção afirma-se:","options":{"A":"paciente na primeira consulta IgM negativo e IgG positivo deve receber tratamento com espiramicina.","B":"paciente com IG de 20 semanas com IgM e IgG positivos deve realizar o teste de avidez.","C":"teste com avidez alta (> 60% representa infecção há mais de 3 ou 4 meses.","D":"o diagnóstico da infecção fetal por meio da amniocentese e pesquisa de PCR no líquido amniótico não é mais utilizado."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320451","ankiGuid":"M_!11H!@(}"},{"id":"anki-obstetricia-infeccoes-congenitas-b940649ddc63eaeb","number":"0349s","sourceNumber":"0349s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Uma criança de três meses de idade, avaliada em consulta de puericultura, é classificada, pelas curvas de crescimento da Organização Mundial de Saúde, como portadora de muito baixo peso e com perímetro cefálico abaixo do esperado para a idade. É internada para investigação do quadro, sendo solicitada tomografia de crânio que demonstrou calcificações intracranianas periventriculares. Acerca desse caso clínico e considerando os conhecimentos médicos correlatados, julgue o item a seguir. O rastreio dessa infecção durante a gestação é preconizado pelas diretrizes do Ministério da Saúde.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320452","ankiGuid":"rqmJz$07Bc"},{"id":"anki-obstetricia-infeccoes-congenitas-be637403df8d9721","number":"0350s","sourceNumber":"0350s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Em relação à rubéola na gravidez, assinale a alternativa INCORRETA:","options":{"A":"A rubéola é uma doença infecciosa aguda virótica causada pelo vírus da família “Togaviridae”, sendo que a infecção ocorre de forma horizontal ou vertical.","B":"Os sintomas são inespecíficos no período prodrômico da rubéola, e o exantema quando surge é do tipo maculopapilar fino.","C":"A principal forma de transmissão dessa doença é a vertical e os mecanismos de danos ao feto ocorrem por lesões intensas e bem localizadas.","D":"O diagnóstico clínico de rubéola é muito difícil por algumas razões. Dentre elas os vários tipos de exantema que são atribuídos à rubéola e vice-versa."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320453","ankiGuid":"gJVD:%lK$a"},{"id":"anki-obstetricia-infeccoes-congenitas-44622ecf8437a027","number":"0354s","sourceNumber":"0354s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Uma paciente de 21 anos de idade, em acompanhamento pré-natal, apresentou sorologias pareadas para toxoplasmose , evidenciando aumento de cinco vezes no valor dos títulos de IgG em um intervalo de três semanas. Julgue o item a seguir O risco de transmissão de toxoplasmose para o feto reduz com a duração da gravidez, sendo no mínimo no terceiro trimestre.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320457","ankiGuid":"eg:{l*63^/"},{"id":"anki-obstetricia-infeccoes-congenitas-9978bdc00b95d043","number":"0355s","sourceNumber":"0355s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Uma paciente de 21 anos de idade, em acompanhamento pré-natal, apresentou sorologias pareadas para toxoplasmose , evidenciando aumento de cinco vezes no valor dos títulos de IgG em um intervalo de três semanas. Julgue o item a seguir. Baixa avidez de IgG para toxoplasmose indica infecção há mais de três meses.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320458","ankiGuid":"ph4_w0SGeM"},{"id":"anki-obstetricia-infeccoes-congenitas-32c9592f86386787","number":"0356s","sourceNumber":"0356s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Uma paciente de 21 anos de idade, em acompanhamento pré-natal, apresentou sorologias pareadas para toxoplasmose , evidenciando aumento de cinco vezes no valor dos títulos de IgG em um intervalo de três semanas. Julgue o item a seguir. O aumento nos títulos de IgG indicam infecção aguda.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320459","ankiGuid":"q9mQ@a9/Gb"},{"id":"anki-obstetricia-infeccoes-congenitas-829e4c69f6f8f797","number":"0357s","sourceNumber":"0357s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"A Região Nordeste, em outubro de 2015, registrou um aumento alarmante dos casos de microcefalia congênita. Neste mesmo tempo, surgiu o surto de ZIKA VÍRUS NA REGIÃO, o que levou a comunidade científica a correlacionar o ZIKA VÍRUS à microcefalia. Em 2016, após estudos da OMS (Organização Mundial da Saúde) e CDC (Center of Disease Control and Prevention), os pesquisadores concluíram que já estavam em posse de provas suficientes para sustentar tal afirmação. Com base na relevância clínica e epidemiológica desta associação, o médico Residente deve estar atento a essa relação. No Estado de Pernambuco, em outubro de 2015, foram notificados 58 casos de recém- nascidos com microcefalia congênita. Esse número foi muito superior ao registrado em 2014 e 2013, 12 e 10 casos, respectivamente. Esses casos foram notificados no SISNAC (Sistema Nacional de Nascidos Vivos). Diante desses dados notificados no SISNAC, o Ministério da Saúde (MS) publicou o primeiro boletim Epidemiológico, o qual registrava 399 casos de Microcefalia, em sete Estados da Região Nordeste, sendo a maioria no Estado de Pernambuco. Em novembro de 2015, o MS declarou Emergência em Saúde Pública de importância Nacional e enviou a todas as Secretarias de Estado orientações sobre notificação, vigilância e assistência às gestantes e aos Recém- nascidos, acometidos pela microcefalia. Ao considerar a possibilidade da associação de infecção congênita por ZIKA VÍRUS e microcefalia, podemos afirmar que:","options":{"A":"A microcefalia é definida por perímetro cefálico inferior a dois desvios-pradão (DP), abaixo da média para o sexo e idade gestacional. É considerada severa quando o PC for inferior a três DP.","B":"Exames de neuroimagem, como Ultrassonografia Fetal e Tomografia Computadorizada do crânio, foram muito inespecíficas para afirmar essa comparação.","C":"Pesquisadores obtiveram resultados insatisfatórios ao comparar a existência de ZIKA VÍRUS em líquido amniótico de gestantes com microcefalia.","D":"Microcefalia pode estar associada ao ZIKA VÍRUS apenas quando o vírus acometer a gestante em seu primeiro trimestre de gestação.","E":"O Ministério da Saúde ainda não conseguiu estudos suficientes para comprovar cientificamente a relação entre ZIKA VÍRUS e microcefalia, aguardando ainda estudos mais específicos."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320460","ankiGuid":"qgl8</4{U{"},{"id":"anki-obstetricia-infeccoes-congenitas-3b605f2d7ad92c07","number":"0358s","sourceNumber":"0358s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Uma gestante realizou sorologia pré-natal de toxoplasmose com doze semanas, obtendo resultado positivo para IgG e IgM. As demais sorologias foram negativas. O médico iniciou espiramicina 3 g/dia e solicitou teste de avidez IgG, realizado à 14.ª semana, cujo resultado foi igual a 65% (alta avidez). Considerando esse caso hipotético, assinale a alternativa que apresenta a melhor conduta médica.","options":{"A":"iniciar imediatamente esquema com sulfadiazina, pirimetamina e ácido folínico,suspendendo-se a espiramicina","B":"realizar amniocentese com vinte semanas para PCR do toxoplasma no líquido amniótico","C":"iniciar esquema com sulfadiazina, pirimetamina e ácido folínico, alternando-se com espiramicina","D":"considerar infecção antiga e suspender a medicação","E":"manter espiramicina até a 36.ª semana de gravidez"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320461","ankiGuid":"s;JDuYeg00"},{"id":"anki-obstetricia-infeccoes-congenitas-a72156b0db49e093","number":"0359s","sourceNumber":"0359s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"O método diagnóstico mais simples e preciso para toxoplasmose fetal é:","options":{"A":"IgM e IgG no sangue fetal","B":"IgM no sangue fetal","C":"IgA no líquido amniótico","D":"PCR-DNA no líquido amniótico","E":"Hidrocefalia na ultrassonografia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320462","ankiGuid":"KkYg2&ktGE"},{"id":"anki-obstetricia-infeccoes-congenitas-4b51527c0cda0222","number":"0360s","sourceNumber":"0360s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Paciente primigesta, 18 anos, iniciou pré-natal com 9 semanas de idade gestacional e tem os seguintes resultados sorológicos para toxoplasmose: 11 semanas: IgG e IgM não reagentes; 22 semanas: IgG não reagente e IgM reagente; 24 semanas: IgG reagente, IgM reagente e baixa avidez de IgG. Com base nos dados, assinale a alternativa correta.","options":{"A":"Trata-se de falso-positivo de IgM; não há risco para o feto.","B":"Sempre que o teste de avidez IgG der baixa avidez, é soroconversão há menos de 4 meses.","C":"Soroconversão aguda para toxoplasmose no 2º trimestre; iniciar tratamento com espiramicina e investigar infecção fetal.","D":"Provável caso de soroconversão recente, já que o teste de avidez foi feito após 16 semanas após a infecção.","E":"O IgM fica positivo por apenas 2 meses."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320463","ankiGuid":"f[=)hTaLZb"},{"id":"anki-obstetricia-infeccoes-congenitas-0e0a21f5d2c6adc1","number":"0361s","sourceNumber":"0361s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante de 12 semanas comparece a consulta de pré-natal com exame de sorologia para Citomegalovirus IgM + e IgG +. A conduta apropriada nesse momento é:","options":{"A":"Solicitar teste de Avidez de IgG para Citomegalovírus.","B":"Iniciar tratamento imediato.","C":"Repetir a sorologia imediatamente.","D":"Indicar aborto terapêutico."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320464","ankiGuid":"F7$Xc7S~~B"},{"id":"anki-obstetricia-infeccoes-congenitas-b776b12746ed4000","number":"0362s","sourceNumber":"0362s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Infecção materna que sabidamente pode causar defeito congênito:","options":{"A":"Influenza.","B":"Citomegalovírus.","C":"Caxumba.","D":"AIDS."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320465","ankiGuid":"OHh#dxDQ>+"},{"id":"anki-obstetricia-infeccoes-congenitas-7cd7af1d1a0de05b","number":"0363s","sourceNumber":"0363s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Em relação à toxoplasmose adquirida durante a gestação, é CORRETO afirmar:","options":{"A":"A espiramicina é capaz de tratar a infecção fetal, se iniciada no 2º trimestre.","B":"A chance de transmissão vertical aumenta quanto maior a idade gestacional.","C":"Após teste de IgM positivo, o tratamento com derivados da penicilina deve ser mantido até o parto.","D":"A presença de IgM positiva com IgG positiva com alta avidez indica contágio recente, inferior a 4 meses.","E":"Quando a pesquisa de toxoplasma por PCR no líquido amniótico for negativa, não é necessário tratamento medicamentoso."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320466","ankiGuid":"MjCR0z(vDK"},{"id":"anki-obstetricia-infeccoes-congenitas-7954b2b58e40113b","number":"0364s","sourceNumber":"0364s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"O teste de avidez em IgG pode ser utilizado para definir a necessidade de tratamento durante a gestação, com o objetivo de reduzir a transmissão vertical para:","options":{"A":"HIV-1.","B":"Sífilis.","C":"Toxoplasmose.","D":"Hepatite B."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320467","ankiGuid":"Q>6;[AH%!F"},{"id":"anki-obstetricia-infeccoes-congenitas-4953b6c7ecc68140","number":"0365s","sourceNumber":"0365s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Considerando as ações de vigilância em saúde para se reduzir a transmissão e a incidência de arboviroses e seu impacto na saúde, recomenda-se que:","options":{"A":"em um paciente com febre, deve-se realizar o diagnóstico diferencial com outras causas de doença febril, avaliar a presença de fenômeno hemorrágico, hipotensão, dor abdominal ou vômitos, mas não havendo sinais de gravidade, pode liberá-lo com orientações","B":"o indivíduo se proteja contra o mosquito Aedes aegypti, conforme as orientações do Ministério da Saúde, que incluem manter portas e janelas fechadas ou teladas, usar calça, camisa de manga comprida, meias e sapatos fechados e utilizar repelentes durante a noite","C":"após confirmação diagnóstica, deve-se, obrigatoriamente, notificar as vigilâncias epidemiológicas municipais, em até 15 dias a partir do conhecimento de sua ocorrência, por meio de ficha de investigação so Sistema de Informação de Agravos de Notificação (SINAN)","D":"nos casos suspeitos, deve-se solicitar o hemograma completo e duas aliquotas de sangue: uma para o diagnóstico de outras infecções e a outra para biologia molecular do Zika Vírus, tendo em vista a relação causal entre a infecção materna por este vírus e a ocorrência de microcefalia fetal"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320468","ankiGuid":"ieP.pY}Mwq"},{"id":"anki-obstetricia-infeccoes-congenitas-55878ce1deaaa2e8","number":"0366s","sourceNumber":"0366s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Assinale a assertiva correta em relação à sífilis congênita.","options":{"A":"A transmissão se dá por via placentária, não havendo risco de contaminação via canal de parto.","B":"O risco de aborto espontâneo ou natimorto é pequeno.","C":"A periostite é um sinal precoce e requer tratamento específico, com imobilização temporária por meio de colete.","D":"Gestantes alérgicas à penicilina devem ser tratadas com doxiciclina por 15 dias na sífilis precoce e 30 dias na tardia.","E":"Recém nascidos de mães com sífilis não tratada devem ser rastreados com hemograma, radiografia (RX) de ossos longos e punção lombar independentemente do resultado do seu VDRL."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320469","ankiGuid":"j.l~vdDQJ<"},{"id":"anki-obstetricia-infeccoes-congenitas-6ec883fdc025075b","number":"0367s","sourceNumber":"0367s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Joana, 22 anos, G1P0, IG:20 semanas, realizou a primeira sorologia para Toxoplasmose com resultado IgG e IgM positivos. Seu obstetra prescreveu espiramicina na dose diária de 3g/dia, e orientou que realizasse nova sorologia em 3 semanas. Qual o objetivo do tratamento prescrito?","options":{"A":"Profilaxia de transmissão vertical.","B":"Tratamento da infecção fetal.","C":"Tratamento da infecção materna.","D":"Tratamento da infecção materno-fetal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320470","ankiGuid":"NtT;FqJr1p"},{"id":"anki-obstetricia-infeccoes-congenitas-c31727b7f8080f56","number":"0368s","sourceNumber":"0368s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Você recebe uma gestante de 30 anos, secundigesta, para seguimento de pré-natal. Comparece com resultados de exames solicitados às 17 semanas de gestação: Hemograma: hemoglobina: 13,0g/dL, glicemia de jejum: 82mg/dL, urocultura: não houve crescimento bacteriano, HbSAG: não reagente, HVI: não reagente, VDRL: não reagente, anti-HIV: não reagente, sorologia para toxoplasmose: IGG negativo e IgM positivo crescente. Assinale a alternativa que apresenta a conduta inicial CORRETA a ser adotada para a paciente:","options":{"A":"Iniciar espiramicina e programar para amniocentese.","B":"Tranquilizar a gestante, pois nesta idade o risco para o feto é mínimo.","C":"Iniciar pirimetacina e programar para amniocentese.","D":"Solicitar teste de avidez para avaliar chance de infecção fetal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320471","ankiGuid":"g>3XpJ$.<r"},{"id":"anki-obstetricia-infeccoes-congenitas-2565529d4c018419","number":"0369s","sourceNumber":"0369s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante com IG 15 semanas comparece a consulta de rotina no Pré-natal para mostrar resultado de exames solicitados. Ao avaliar os resultados, o Médico de Família e Comunidade observa que a sorologia para toxoplasmose apresenta resultado IgG positiva e IgM positiva. Qual o primeiro passo a conduta preconizada para a Atenção primária à Saúde?","options":{"A":"Repetir a sorologia para toxoplasmose","B":"Solicitar teste de avidez","C":"Encaminhar para o pré-natal de alto risco","D":"Nenhuma das alternativas está correta"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320472","ankiGuid":"cV]D2c-BWI"},{"id":"anki-obstetricia-infeccoes-congenitas-16c2ab049eea012c","number":"0370s","sourceNumber":"0370s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"As sequelas fetais decorrentes de infecções adquiridas na gestação são frequentes e geralmente relacionadas a: sífilis, toxoplasmose, citomegalovirus (CMV), rubéola ou herpes. Qual das alternativas abaixo engloba a resposta CORRETA sobre este tema?","options":{"A":"Indica-se a realização de abortamento em gestantes que realizaram a vacinação inadvertida contra rubéola durante a gestação.","B":"No feto com infecção comprovada por toxoplasmose, indica-se a realização de parto cesariano.","C":"Está indicada a realização de parto cesariano em gestantes com herpes genital ativa no trabalho de parto.","D":"É obrigatória a solicitação de sorologias para CMV e rubéola durante a gestação, pois apresenta terapêutica efetiva."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320473","ankiGuid":"JOjl/@T#+Y"},{"id":"anki-obstetricia-infeccoes-congenitas-e5ab5f69ecbd3c7b","number":"0371s","sourceNumber":"0371s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Tratamento da toxoplasmose na gestação A toxoplasmose é uma zoonose causada pelo Toxoplasma gondii e adquire especial relevância quando atinge a gestante, visto o elevado risco de acometimento fetal, segundo o Manual de Gestação de Alto Risco do Ministério da Saúde. Em relação a esse tema, assinale a opção INCORRETA","options":{"A":"Se no primeiro exame solicitado na primeira consulta para rastreamento de toxoplasmose, detectam-se anticorpos IgM, caso a gestação tenha mais de 16 semanas, deve ser feito imediatamente o teste de avidez de IgG, na mesma amostra de soro.","B":"Na presença de anticorpos IgG positivos e IgM negativos, considera-se a gestante imune.","C":"Entre os agravos a atômicos e funcionais decorrentes da toxoplasmose congênita, podem ser descritos restrição de crescimento intrauterino, morte fetal, prematuridade e/ou manifestações, clínicas e sequelas como microftalmia, lesões oculares, microcefalia, hidrocefaliia, calcificações cerebrais, pneumonite, hepatoesplenomegalia, erupção cultânea e retardo mental.","D":"Embora não exista consenso sobre o real benefício do rastreamento universal para toxoplasmose na gravidez, o Ministério da Saúde recomenda a realização da triagem sorológica, principalmente em lugares onde a prevalência é elevada.","E":"A maioria dos casos de toxoplasmose pode acontecer sem sintomas ou com sintomas bastante inespecíficos. Mesmo na ausência de sintomatologia, o diagnóstico da infecção aguda pelo Toxoplasma gondii na gravidez se reveste de importância, tendo como objetivo principal a prevenção da toxoplasmose congênita e suas sequelas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320474","ankiGuid":"CnfVG8%5AW"},{"id":"anki-obstetricia-infeccoes-congenitas-45c5c3e0dae90f41","number":"0372s","sourceNumber":"0372s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Tratamento da toxoplasmose na gestação Uma gestante de 35 anos iniciou pré-natal com 12 semanas de gravidez, momento em que apresentou, na sorologia para toxoplasmose, IgG e IgM negativos. Agora está com 24 semanas, e nova sorologia solicitada para a mesma doença mostra IgG e IgM positivos. Não há comorbidades. Qual é a melhor conduta nesse momento?","options":{"A":"realizar teste de avidez IgG","B":"iniciar espiramicina 3g/d e indicar amniocentese","C":"iniciar tratamento com sulfadiazina, pirimetamina e ácido folínico, alternados com espiramicina","D":"realizar seguimento pré-natal habitual, sem necessidade de uso de medicação específica para toxoplasmose ou outras medidas investigativas"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320475","ankiGuid":"mq&7pIpkGN"},{"id":"anki-obstetricia-infeccoes-congenitas-7ae14db3f6e0f2e6","number":"0373s","sourceNumber":"0373s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestação de 10 semanas, com lgG e lgM para toxoplasmose positivos e teste de avidez para lgG mostrando baixa avidez. Com base neste quadro, o diagnóstico e a conduta adequada são, respectivamente:","options":{"A":"infecção recente - iniciar imediatamente o tratamento com espiramicina.","B":"infecção recente - iniciar imediatamente o tratamento com esquema tríplce (espiramicina, sulfadiazina, acido folínico).","C":"infecção tardia - aguardar até 12 semanas e iniciar o tratamento com espiramicina.","D":"infecção tardia - tranquilizar a gestante."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320476","ankiGuid":"qVb7ri(R)h"},{"id":"anki-obstetricia-infeccoes-congenitas-9655a9fa41e30b14","number":"0374s","sourceNumber":"0374s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Em áreas endêmicas, casais que desejam a concepção devem ser orientados quanto aos riscos da infecção pelo vírus Zika e a possibilidade de malformações fetais. Sendo INCORRETO que","options":{"A":"a transmissão sexual do vírus Zika foi comprovada por inúmeros relatos de casos, sendo a Zika considerada uma IST, cuja transmissão sexual pode ser evitada por meio do uso de preservativo.","B":"para casais que desejam a concepção, recomenda-se aguardar até 2 meses após sinais/sintomas relacionados à infecção pelo vírus Zika quando o homem foi infectado.","C":"deve ser reforçada a importância do uso do preservativo, especialmente após viagens a áreas endêmicas ou suspeita e/ou confirmação do diagnóstico da infecção pela parceria sexual.","D":"isso porque a persistência das partículas virais foi observada em fluidos corporais, como sêmen."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320477","ankiGuid":"sQyb6)]*;-"},{"id":"anki-obstetricia-infeccoes-congenitas-41bb5dda654e91be","number":"0375s","sourceNumber":"0375s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Paciente de 24 anos vem para a consulta de pré-natal para mostrar o primeiro teste da mamãe. O resultado foi o seguinte: toxoplasmose IgG e IgM negativos; rubéola IgG e IgM negativos; citomegalovírus IgG positivo e IgM negativo. Demais testes não reagentes. A conduta frente ao caso seria:","options":{"A":"Orientar a paciente a tomar vacina contra rubéola;","B":"Realizar sorologia trimestral de toxoplasmose e orientar a mãe a não manipular jardins ou caixas de areia com fezes de gatos, não consumir carne crua, não consumir verduras ou água que ela não tenha certeza sobre a higienização ou filtragem adequada;","C":"Prosseguir o pré-natal normalmente, sem qualquer orientação especial;Informar à mãe que ela foi infectada pelo citomegalovírus na gestação, e que a criança pode apresentar malformações.","D":"Informar à mãe que ela foi infectada pelo citomegalovírus na gestação, e que a criança pode apresentar malformações."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320478","ankiGuid":"g;q7-OG?1I"},{"id":"anki-obstetricia-infeccoes-congenitas-69669f431e97190b","number":"0376s","sourceNumber":"0376s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante chega à maternidade com idade gestacional de 40 semanas, com carta de encaminhamento para indução do parto. Durante o exame, é constatada lesão ativa de herpes genital. A conduta é:","options":{"A":"Prescrever medicação antiviral por 24h e, posteriormente, proceder à indução do parto.","B":"Proceder à indução e não realizar episiotomia.","C":"Proceder à indução e abreviar o período expulsivo.","D":"Indicar cesariana."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320479","ankiGuid":"n>bXkQF`73"},{"id":"anki-obstetricia-infeccoes-congenitas-081ea8b25be0d172","number":"0377s","sourceNumber":"0377s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Primigesta, idade gestacional de 14 semanas, apresenta, na primeira consulta de pré- natal, IgM positivo e IgG negativo para toxoplasmose. Qual medicação é utilizada com a finalidade de reduzir a transmissão vertical do Toxoplasma gondii neste caso?","options":{"A":"Prometamina.","B":"Espiramicina.","C":"Rifampicina.","D":"Sulfasalazina.","E":"Pirimetamina."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320480","ankiGuid":"FkT<9m_&c<"},{"id":"anki-obstetricia-infeccoes-congenitas-d491a127c2e1480b","number":"0378s","sourceNumber":"0378s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"O ultrassom obstétrico de 1º trimestre revela feto único, vivo, com comprimento cabeça nádega de 50mm, BCF 160bpm e translucência nucal igual a 6,6mm. A placenta apresenta-se com várias áreas císticas em meio a tecido trofoblástico normal. Qual é a mais provável hipótese diagnóstica?","options":{"A":"Abortamento retido","B":"Placenta prévia","C":"Fetopatia por rubéola","D":"Mola hidatiforme parcial"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320481","ankiGuid":"faMOQJhh.b"},{"id":"anki-obstetricia-infeccoes-congenitas-bcbdaea76ba4d93e","number":"0379s","sourceNumber":"0379s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Mulher de 19 anos de idade recebeu vacina de rubéola e, na semana seguinte, descobriu estar grávida de 8 semanas. Nesse momento, recomenda-se","options":{"A":"IGG e IGM para rubéola no sangue materno.","B":"Sugerir interrupção da gestação.","C":"Pcr para rubéola no líquido amniótico na 14ª semana.","D":"Amniocentese com pesquisa de IGM para rubéola."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320482","ankiGuid":"K3!jq/aTWN"},{"id":"anki-obstetricia-infeccoes-congenitas-33ce2a9773be4835","number":"0380s","sourceNumber":"0380s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Assinale a questão incorreta:","options":{"A":"Após o teste rápido para Sífilis e VDRL negativos no acolhimento, deve-se repetir o exame no 3º trimestre (28ª semana), no momento do parto e em caso de abortamento.","B":"A maioria dos casos de toxoplasmose pode acontecer sem sintomas ou com sintomas bastante inespecíficos, portanto, os casos positivos não precisam ser notificados.","C":"Gestante soronegativa para toxoplasmose IgG (-) e IgM (-) deve-se realizar a prevenção primária e repetir a sorologia de três em três meses e no momento do parto.","D":"Gestante IgG (+) e IgM (+) para toxoplasmose: possibilidade de infecção durante a gestação, portanto, realizar teste de avidez de IgG na mesma amostra."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320483","ankiGuid":"KAq~--FLUR"},{"id":"anki-obstetricia-infeccoes-congenitas-080c97db95567c5d","number":"0381s","sourceNumber":"0381s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Os principais efeitos teratogênicos da rubéola são:","options":{"A":"Microcefalia, catarata, surdez e cardiopatia.","B":"Microcalcificações cerebrais, microcefalia, coriorretinite.","C":"Focomelia e cardiopatia.","D":"Hipospádia em meninos e virilização meninas.","E":"Nenhuma das anteriores."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320484","ankiGuid":"wpCFbg^RMe"},{"id":"anki-obstetricia-infeccoes-congenitas-cab49be653fb9845","number":"0382s","sourceNumber":"0382s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante de 11 semanas, tem resultado de sorologia para toxoplasmose mostrando IgM positiva, IgG positiva com baixa avidez. Indica-se","options":{"A":"sulfadiazina + azitromicina.","B":"sulfadiazina + pirimetamina.","C":"espiramicina.","D":"repetir a sorologia em 2 semanas.","E":"seguimento pré-natal (infecção antiga)."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320485","ankiGuid":"g:7?2cyp#s"},{"id":"anki-obstetricia-infeccoes-congenitas-776392b9c9cd2a58","number":"0383s","sourceNumber":"0383s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Em relação ao Citomegalovírus na gravidez, assinale a afirmativa CORRETA.","options":{"A":"O rastreamento universal é obrigatório.","B":"É a principal causa de defeitos abertos do tubo neural.","C":"Pode ser diagnosticado pelo ultrassom com medida de translucência nucal.","D":"Pode ser causa de surdez neurossensorial e retardo mental."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320486","ankiGuid":"K3y:oS2aS>"},{"id":"anki-obstetricia-infeccoes-congenitas-10d28ed1722ecf20","number":"0384s","sourceNumber":"0384s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Paciente primigesta apresenta anticorpos lgG e lgM negativos para toxoplasmose no primeiro trimestre. Com 30 semanas, traz sorologia para toxoplasmose lgG negativo e lgM positivo. Qual é a conduta adequada?","options":{"A":"Solicitar avidez da lgM e retornar em 1 semana.","B":"Iniciar espiramicina, solicitar amniocentese e repetir exames.","C":"Tranquilizar a paciente, pois não há mais risco de infecção fetal.","D":"Realizar amniocentese e, conforme o resultado, iniciar tratamento.","E":"Repetir exames e mandar retornar em 3 semanas, pois os falsos positivos são frequentes."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320487","ankiGuid":"vORSrJ:RN3"},{"id":"anki-obstetricia-infeccoes-congenitas-8ac82a5ed72927aa","number":"0385s","sourceNumber":"0385s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"O teste de avidez em IgG pode ser utilizado para definir a necessidade de tratamento durante a gestação, com o objetivo de reduzir a transmissão vertical para:","options":{"A":"Hepatite B.","B":"Sífilis.","C":"Hepatite C.","D":"Toxoplasmose."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320488","ankiGuid":"N!mO#{^2W@"},{"id":"anki-obstetricia-infeccoes-congenitas-1bfc66083caca74a","number":"0386s","sourceNumber":"0386s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Em relação aos aspectos gerais do diagnóstico de infecções congênitas, podem-se afirmar :","options":{"A":"A infecção fetal na primeira metade da gestação é menos frequente sendo maior a probabilidade de morte do embrião e infecção sintomática","B":"Os anticorpos IgM maternos, contendo anticorpos contra microrganismos aos quais a mãe tenha sido expostas previamente, passam ativamente através da placenta a partir da segunda metade da gestação","C":"Os níveis máximos de anticorpos maternos IgG são atingidos na primeira metade da gestação, declinando a níveis indetectáveis após período variável de tempo","D":"Diferentemente das técnicas que detectam anticorpo específico materno IgM, IgA e IgE, os ensaios para detecção de anticorpos IgG não auxiliam no diagnóstico de infecções congênitas, pois esses anticorpos não atravessam a placenta devido ao seu elevado peso molecular","E":"Geralmente a placenta é menos permeável à passagem de agentes microbianos quanto mais tardia a gestação, protegendo menos eficientemente o feto no final dessa"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320489","ankiGuid":"A!GcI|-F}y"},{"id":"anki-obstetricia-infeccoes-congenitas-79562555c31b255d","number":"0387s","sourceNumber":"0387s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante de 25 anos na 10ª semana apresenta IgG e IgM positivas para toxoplasmose, com avidez da IgG alta. A melhor conduta nesse caso é:","options":{"A":"Recomendar a interrupção da gravidez.","B":"Realizar amniocentese com 16 semanas para fazer PCR do líquido amniótico.","C":"Orientar o casal que a infecção é passada.","D":"Iniciar tratamento fetal com sulfadiazina e pirimetamina.","E":"Indicar espiramicina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320490","ankiGuid":"jL/pid+*Uw"},{"id":"anki-obstetricia-infeccoes-congenitas-78e34651c42dd112","number":"0388s","sourceNumber":"0388s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Primigesta é atendida no plantão da maternidade com quadro de exantema maculopapular. Em virtude da epidemia de Zika vírus, é solicitada investigação, com PCR confirmando a infecção. Entre as ocorrências mais frequentes no recém-nascido, verifica- se:","options":{"A":"Anencefalia.","B":"Agenesia renal.","C":"Membros curtos.","D":"Calcificações periventriculares."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320491","ankiGuid":"EA%>EhQ`at"},{"id":"anki-obstetricia-infeccoes-congenitas-06a0d66c94aaabc3","number":"0389s","sourceNumber":"0389s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Qual das infecções abaixo está comumente associada à anemia fetal?","options":{"A":"Citomegalovírus.","B":"Parvovírus.","C":"Herpes.","D":"Sífilis.","E":"Toxoplasmose."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320492","ankiGuid":"op/6a)gL[["},{"id":"anki-obstetricia-infeccoes-congenitas-f2ccee3751ade0c3","number":"0390s","sourceNumber":"0390s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante de 8 semanas, assintomática nos últimos dois meses, traz os seguintes exames de rotina pré-natal: sorologia para toxoplasmose com imunofluorescência indireta positiva para IgG e IgM, além de teste ELISA IgG de Avidez para toxoplasmose = 85%. Dentre as opções abaixo a conduta mais adequada é:","options":{"A":"informar à paciente de que a mesma adquiriu a infecção no primeiro trimestre de gestação, podendo haver graves sequelas para o feto e realizar o abortamento terapêutico.","B":"informar à paciente de que a mesma adquiriu a infecção no primeiro trimestre de gestação, podendo haver graves sequelas para o feto, mas manter a gravidez.","C":"informar à paciente de que a mesma muito provavelmente adquiriu a infecção antes da gestação e que os riscos para o feto são mínimos com relação à toxoplasmose.","D":"realizar imediatamente amniocentese diagnóstica para pesquisa de toxoplasmose fetal.","E":"realizar imediatamente Cordocentese diagnóstica para pesquisa de toxoplasmose fetal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320493","ankiGuid":"b0iNI*v7$a"},{"id":"anki-obstetricia-infeccoes-congenitas-58cf14a3bedfdc9f","number":"0391s","sourceNumber":"0391s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Assinale a alternativa que indica sorologias realizadas durante o período gestacional para detectar doenças de transmissão vertical que de algum modo podem ser tratadas.","options":{"A":"HIV, Síflis, Toxoplasmose e Rubéola","B":"Rubéola, Hepatite C, Citomegalovírus, Toxoplasmose","C":"HIV, Síflis, Toxoplasmose, Hepatite B","D":"Toxoplasmose, Síflis, Hepatite B e Doença de chagas","E":"Citomegalovírus, Síflis, Toxoplasmose, HIV"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320494","ankiGuid":"GfR=SE?o[G"},{"id":"anki-obstetricia-infeccoes-congenitas-a610b8a607c4d08b","number":"0392s","sourceNumber":"0392s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"gestação A Toxoplasmose congênita é, em geral, subclínica ao nascimento, podendo a sintomatologia evidenciar-se ao longo do período neonatal e mesmo entre os lactentes. As manifestações mais frequentes são Corioretinite, calcificações intracranianas, hidrocefalia, microcefalia, estrabismo, convulsões e retardo neuro-psico-motor. Gestante primigesta, com idade gestacional de 8 (oito semanas) por DUM e USG (de 6 semamas), procura atendimento com os seguintes resultados laboratoriais: Sorologia para Toxoplasmose IgG > 650, 00 (POSITIVO), e sorologia para Toxoplasmose IgM 8, 7 (POSITIVO). Diante deste quadro (infecção aguda), qual a conduta mais apropriada?","options":{"A":"Iniciar imediatamente Espiramicina.","B":"Solicitar avidez para Toxoplasmose igg.","C":"Iniciar imediatamente esquema tríplice (Pirimetamina + Sulfadiazina + Ácido Folínico).","D":"Indicar imediatamente PCR no líquido amniótico.","E":"As alternativas A e B estão corretas."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320495","ankiGuid":"I[E@y&fy2|"},{"id":"anki-obstetricia-infeccoes-congenitas-6013660e4bfd4060","number":"0393s","sourceNumber":"0393s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Em relação ao agente etiológico da toxoplasmose, analise as afirmativas abaixo. I - Apresenta três formas durante o seu ciclo de vida: oocistos, taquizoítos e bradizoítos.; II - É um protozoário extracelular que acomete preferencialmente o sistema nervoso central.; III - O parasita se multiplica no intestino dos felinos e os oocistos resultantes são eliminados nas fezes.; IV - A contaminação humana pode ocorrer pela ingestão de carnes cruas ou frutas, verduras e legumes mal lavados.; Está CORRETO o que se afirma em:","options":{"A":"I, III e IV, apenas.","B":"II e IV, apenas.","C":"II e IV, apenas.","D":"III e IV, apenas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320496","ankiGuid":"BJZV[k!)]J"},{"id":"anki-obstetricia-infeccoes-congenitas-857e08ff150e99a1","number":"0394s","sourceNumber":"0394s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Tratamento da toxoplasmose na gestação Gestante com 18 semanas de idade gestacional, inicia a primeira consulta de pré- natal, na UBS e todos os exames são normais, exceto a sorologia para toxoplasmose que se mostrou positiva (IgG e IgM positivos). O teste de avidez foi fraco. Qual o possível diagnóstico e conduta?","options":{"A":"Provável doença por toxoplasmose recente. Iniciar espiramicina e encaminhar para referência a fim de solicitar PCR no líquido amniótico imediatamente.","B":"Doença por toxoplasmose antiga. Iniciar sulfadiazina e encaminhar para referência imediatamente.","C":"Provável doença por toxoplasmose recente. Iniciar esquema antibiótico com rifampicina e encaminhar para referência imediatamente.","D":"Provável doença por toxoplasmose recente. Iniciar espiramicina com ácido folínico e encaminhar para cordocentese imediatamente.","E":"Provável doença por toxoplasmose antiga. Seguir pré-natal de baixo risco normalmente."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320497","ankiGuid":"suV*.C}+=R"},{"id":"anki-obstetricia-infeccoes-congenitas-5ac625662063bcb2","number":"0395s","sourceNumber":"0395s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Uma paciente de 27 anos, na 3' gestação, com 2 partos vaginais anteriores, inicia o pré-natal em uma unidade de saúde de Curitiba. Faltou 2 vezes à coleta de exames laboratoriais de 1° trimestre e vem com resultados de exames de rotina. A coleta dos exames foi realizada, há 1 semana, com 18 semanas de idade gestacional. Apresentou sorologia para toxoplasmose reagente (IgM e IgG) e avidez forte para IgG. Para essa paciente, a melhor conduta, segundo o protocolo Mãe Curitibana, é:","options":{"A":"iniciar espiramicina.","B":"intercalar espiramicina com esquema tríplice a cada 2 semanas.","C":"não realizar qualquer tratamento.","D":"iniciar esquema tríplice com pirimetamina, sulfadiazina e ácido folínico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320498","ankiGuid":"GnNi=6;=$P"},{"id":"anki-obstetricia-infeccoes-congenitas-2f6c8abffb45a229","number":"0396s","sourceNumber":"0396s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Marina, de 19 anos, primigesta, comparece à consulta de pré-natal na ESF com sorologia para toxoplasmose lgM e IgG positivos, realizados com 12 semanas de idade gestacional. É correto afirmar quanto à interpretação do teste de avidez para IgG no caso acima:","options":{"A":"Teste de avidez de IgG forte (>60%) indica infecção recente;","B":"O teste de avidez de IgG estaria indicado se IgM positivo e IgG negativo.","C":"O teste de avidez de IgG fraco ( < 60%) indica possibilidade de infecção recente.","D":"O teste de avidez para IgG estaria indicado se IgM negativo e IgG positivo."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320499","ankiGuid":"C%NR_,W}dh"},{"id":"anki-obstetricia-infeccoes-congenitas-aaf0a4bb7b4544bf","number":"0397s","sourceNumber":"0397s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Dos patógenos abaixo, aquele que pode comprometer o feto causando calcificações cerebrais, microcefalia e hepatoesplenomegalia é:","options":{"A":"Sarampo.","B":"Citomegalovirus.","C":"Varicela.","D":"Treponema pallidum."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320500","ankiGuid":"JOE.A?+0r4"},{"id":"anki-obstetricia-infeccoes-congenitas-e9d526bf31d35d05","number":"0398s","sourceNumber":"0398s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Gestante a termo, com quadro de rotura prematura das membranas há duas horas, sem metrossístoles, feto vivo e líquido amniótico claro com grumos. Ao exame genital, verificam-se lesões herpéticas ativas em borda inferior do introito vaginal. A conduta, neste caso, é:","options":{"A":"indução do trabalho de parto.","B":"cesariana no momento da internação.","C":"espera da entrada espontânea do trabalho de parto por 12 horas.","D":"cesariana após tratamento do herpes genital."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320501","ankiGuid":"H4MgYiSMJ0"},{"id":"anki-obstetricia-infeccoes-congenitas-5141082abe0e0c61","number":"0399s","sourceNumber":"0399s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Paciente com 10 semanas de gestação apresentando sorologia positiva para citomegalovirus, realiza teste de avidez de IgG cujo resultado foi 87%. Sobre isso, assinale a alternativa CORRETA:","options":{"A":"não há teste de avidez para Citomegalovirus","B":"o teste revela infecção remota","C":"o teste revela infecção recente","D":"não há relação entre a avidez e o risco fetal"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320502","ankiGuid":"PqYYb]_hdO"},{"id":"anki-obstetricia-infeccoes-congenitas-1404ad85b53e20c9","number":"03100s","sourceNumber":"03100s","collectionBlock":"anki:obstetricia-infeccoes-congenitas","collectionLabel":"Anki · Infecções Congênitas","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","subtopic":"","stem":"Mulher, 33 anos, G1P0A0, no primeiro trimestre da gestação (10 semanas de idade gestacional), realiza o acompanhamento pré-natal e traz consigo o resultado do primeiro teste da mamãe. Na leitura do resultado, encontra-se IgG e IgM positivos para toxoplasmose. A interpretação e a conduta frente a esse resultado seriam:","options":{"A":"infecção crônica - solicitar nova investigação no terceiro trimestre;","B":"gestante susceptível - repetir a investigação no terceiro trimestre;","C":"infecção aguda inicial - repetir a sorologia após duas semanas;","D":"infecção subaguda ou recente - solicitar teste de avidez."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Infecções Congênitas","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Infecções Congênitas","Anki"],"ankiNoteId":"1779792320503","ankiGuid":"w)}mQWVgv#"}]};
